'use client';
import { AvatarRoot, AvatarImage, AvatarFallback } from '@gaudi/design-system/core/Avatar';
import {
  formatBytes,
  FileUploadDropzone, useFileUpload
} from '@gaudi/design-system/core/FileUpload';
import {
  Alert,
  AlertDescription,
  AlertTitle
} from '@gaudi/design-system/core/Banner';
import { cn } from '@gaudi/design-system/utilities/cn';
import { default as Button } from '@gaudi/design-system/core/Button';
import { RegistryIcon } from '@gaudi/design-system/icons/RegistryIcon';
export function Pattern({
  maxSize = 2 * 1024 * 1024,
  // 2MB
  className,
  onFileChange,
  defaultAvatar
}) {
  const [
    { files, errors },
    {
      removeFile,
      dropzoneProps,
      openFileDialog,
      getInputProps
    }
  ] = useFileUpload({
    maxFiles: 1,
    maxSize,
    accept: 'image/png,image/jpeg',
    multiple: false,
    onFilesChange: (files2) => {
      onFileChange?.(files2[0] || null);
    }
  });
  const currentFile = files[0];
  const previewUrl = currentFile?.preview || defaultAvatar;
  const handleRemove = () => {
    if (currentFile) {
      removeFile(currentFile.id);
    }
  };
  return (
    <div className={cn('flex flex-col items-center gap-3', className)}>
      {/* Avatar Preview */}
      <div className='relative'>
        <input {...getInputProps({ 'aria-label': 'Choose avatar image' })} className='sr-only' tabIndex={-1} />
        <FileUploadDropzone as={Button} {...dropzoneProps}
          variant='ghost'
          size='icon-lg'
          aria-label='Choose avatar image'
          aria-haspopup='dialog'
          className={cn('size-24 overflow-hidden p-0', previewUrl && 'border-solid')}
          onClick={openFileDialog}
        >
          <AvatarRoot className='size-full rounded-[inherit]'>
            <AvatarImage src={previewUrl} alt='Avatar' />
            <AvatarFallback>
              <RegistryIcon lucide='User' className='size-6 text-text-muted' />
            </AvatarFallback>
          </AvatarRoot>
        </FileUploadDropzone>

        {/* Remove Button - only show when file is uploaded */}
        {currentFile && (
          <Button
            size='icon'
            variant='outline'
            onClick={handleRemove}
            className='absolute end-0.5 top-0.5 z-10 size-6 rounded-control'
            aria-label='Remove avatar'
          >
            <RegistryIcon lucide='XIcon' className='size-3.5' />
          </Button>
        )}
      </div>

      {/* Picker button, file name, and limits */}
      <div className='grid justify-items-center gap-1.5 text-center'>
        <Button size='sm' variant='outline' onClick={openFileDialog} aria-haspopup='dialog'>
          <RegistryIcon lucide='UploadIcon' className='size-3.5' />
          {currentFile ? 'Change image' : 'Upload image'}
        </Button>
        <p className='max-w-56 truncate text-xs text-ui-muted-foreground' aria-live='polite'>
          {currentFile ? currentFile.file.name : `PNG or JPG up to ${formatBytes(maxSize)}`}
        </p>
      </div>

      {/* Error Messages */}
      {errors.length > 0 && (
        <Alert variant='destructive'>
          <RegistryIcon lucide='CircleAlertIcon' />
          <AlertTitle>File upload error(s)</AlertTitle>
          <AlertDescription>
            {errors.map((error, index) => (
              <p key={index} className='last:mb-0'>
                {error}
              </p>
            ))}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
